<?php require_once __DIR__ . '/../src/partials.php';$pdo=db();if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();try{$s=$pdo->prepare('SELECT password_hash FROM users WHERE id=?');$s->execute([current_user_id()]);$u=$s->fetch();if(!$u||!password_verify($_POST['current_password'],$u['password_hash']))throw new Exception('รหัสผ่านปัจจุบันไม่ถูกต้อง');if(strlen($_POST['new_password'])<6)throw new Exception('รหัสผ่านใหม่ต้องมีอย่างน้อย 6 ตัวอักษร');if($_POST['new_password']!==$_POST['confirm_password'])throw new Exception('ยืนยันรหัสผ่านไม่ตรงกัน');$s=$pdo->prepare('UPDATE users SET password_hash=?,updated_at=CURRENT_TIMESTAMP WHERE id=?');$s->execute([password_hash($_POST['new_password'],PASSWORD_DEFAULT),current_user_id()]);flash('success','เปลี่ยนรหัสผ่านเรียบร้อยแล้ว');header('Location:/password.php');exit;}catch(Throwable $e){flash('danger',$e->getMessage());header('Location:/password.php');exit;}}page_start('เปลี่ยนรหัสผ่าน');?><div class="card form-card"><form method="post"><input type="hidden" name="csrf" value="<?=h(csrf())?>"><label>รหัสผ่านปัจจุบัน</label><input type="password" name="current_password" required><label>รหัสผ่านใหม่</label><input type="password" name="new_password" required minlength="6"><label>ยืนยันรหัสผ่านใหม่</label><input type="password" name="confirm_password" required minlength="6"><button class="primary" style="margin-top:16px">เปลี่ยนรหัสผ่าน</button></form></div><?php page_end();
